import React, { useState } from 'react';
import { Box, TextField, Button, Typography, ButtonGroup } from '@mui/material';
import { reviewCode } from '../services/codeReviewService';

interface CodeEditorProps {
  code: string;
  onChange: (code: string) => void;
  onStatusChange: (status: 'completed' | 'failed' | 'abandoned') => void;
  isLoading?: boolean;
}

const CodeEditor: React.FC<CodeEditorProps> = ({ 
  code, 
  onChange, 
  onStatusChange,
  isLoading = false 
}) => {
  const [error, setError] = useState<string | null>(null);

  const handleStatusChange = async (status: 'completed' | 'failed' | 'abandoned') => {
    try {
      setError(null);

      if (status === 'completed' && !code.trim()) {
        setError('Пожалуйста, введите код перед отправкой');
        return;
      }

      if (status === 'completed') {
        const reviewData = await reviewCode(code, '');
        onStatusChange(status);
      } else {
        onStatusChange(status);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Произошла ошибка');
    }
  };

  return (
    <Box sx={{ width: '100%' }}>
      <TextField
        fullWidth
        multiline
        rows={10}
        value={code}
        onChange={(e) => onChange(e.target.value)}
        variant="outlined"
        placeholder="Введите ваш код здесь..."
        error={!!error}
        helperText={error}
        sx={{
          '& .MuiOutlinedInput-root': {
            fontFamily: 'monospace',
            fontSize: '14px',
            backgroundColor: 'grey.900',
            '& fieldset': {
              borderColor: 'grey.700',
            },
            '&:hover fieldset': {
              borderColor: 'grey.500',
            },
            '&.Mui-focused fieldset': {
              borderColor: 'primary.main',
            },
          },
        }}
      />
      <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center', gap: 2 }}>
        <ButtonGroup variant="contained" disabled={isLoading}>
          <Button 
            color="success" 
            onClick={() => handleStatusChange('completed')}
            disabled={isLoading}
          >
            Решено
          </Button>
          <Button 
            color="error" 
            onClick={() => handleStatusChange('failed')}
            disabled={isLoading}
          >
            Не решено
          </Button>
          <Button 
            color="warning" 
            onClick={() => handleStatusChange('abandoned')}
            disabled={isLoading}
          >
            Пропустить
          </Button>
        </ButtonGroup>
      </Box>
    </Box>
  );
};

export default CodeEditor;
